-- squawk-ignore-file prefer-robust-stmts
-- squawk-ignore-file prefer-bigint-over-int
-- squawk-ignore-file require-lock-timeout
-- squawk-ignore-file require-statement-timeout
-- This additive migration is applied atomically by the migration runner. The
-- catalog seed and its insert-only triggers must be installed together.
CREATE TABLE "daily_prompts" (
	"id" text PRIMARY KEY NOT NULL,
	"month_day" text NOT NULL,
	"text" text NOT NULL,
	"version" integer NOT NULL,
	"effective_date" date NOT NULL,
	"source" text NOT NULL,
	"source_commit" text NOT NULL,
	CONSTRAINT "daily_prompts_month_day_version_unique" UNIQUE("month_day","version"),
	CONSTRAINT "daily_prompts_month_day_effective_date_unique" UNIQUE("month_day","effective_date"),
	CONSTRAINT "daily_prompts_id_format_check" CHECK ("daily_prompts"."id" ~ '^prompt-[0-9]{2}-[0-9]{2}(-v[0-9]+)?$'),
	CONSTRAINT "daily_prompts_id_canonical_check" CHECK ("daily_prompts"."id" = 'prompt-' || "daily_prompts"."month_day" || case when "daily_prompts"."version" = 1 then '' else '-v' || "daily_prompts"."version"::text end),
	CONSTRAINT "daily_prompts_month_day_format_check" CHECK ("daily_prompts"."month_day" ~ '^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'),
	CONSTRAINT "daily_prompts_month_day_calendar_check" CHECK (case
		when "daily_prompts"."month_day" !~ '^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' then false
		when substring("daily_prompts"."month_day", 1, 2) in ('01', '03', '05', '07', '08', '10', '12') then substring("daily_prompts"."month_day", 4, 2)::integer <= 31
		when substring("daily_prompts"."month_day", 1, 2) in ('04', '06', '09', '11') then substring("daily_prompts"."month_day", 4, 2)::integer <= 30
		else substring("daily_prompts"."month_day", 4, 2)::integer <= 29
	end),
	CONSTRAINT "daily_prompts_version_positive_check" CHECK ("daily_prompts"."version" > 0),
	CONSTRAINT "daily_prompts_text_length_check" CHECK (char_length("daily_prompts"."text") between 1 and 4000)
);
-- Immutable version-one catalog seed from 732-workspace/group-project-wdcc@7d2dfd6.

-- Prompt rows are insert-only and scheduled versions must advance monotonically.
CREATE FUNCTION public.dayli_daily_prompt_immutable()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'daily_prompts rows are immutable' USING ERRCODE = '55000';
END;
$function$;

CREATE TRIGGER daily_prompts_immutable_trigger
BEFORE UPDATE OR DELETE ON public.daily_prompts
FOR EACH ROW EXECUTE FUNCTION public.dayli_daily_prompt_immutable();

CREATE FUNCTION public.dayli_daily_prompt_schedule_guard()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  -- Serialize schedules for one month-day so concurrent inserts cannot both
  -- pass the visibility check before either transaction commits.
  PERFORM pg_advisory_xact_lock(734003, hashtext(NEW.month_day));

  IF EXISTS (
    SELECT 1
    FROM public.daily_prompts existing
    WHERE existing.month_day = NEW.month_day
      AND (existing.version >= NEW.version OR existing.effective_date >= NEW.effective_date)
  ) THEN
    RAISE EXCEPTION 'daily_prompts versions require a later Auckland effective date and version' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE TRIGGER daily_prompts_schedule_guard_trigger
BEFORE INSERT ON public.daily_prompts
FOR EACH ROW EXECUTE FUNCTION public.dayli_daily_prompt_schedule_guard();
